/// Cloudflare bindings consumed by the server layer (RPC + auth).
///
/// This is the subset of `Cloudflare.Env` (generated by `wrangler types`) that
/// the server depends on. Named `AppEnv` to avoid accidental declaration
/// merging with the generated global `Env`.
interface AppEnv {
  BETTER_AUTH_SECRET: string;
  BETTER_AUTH_URL: string;
  DB: D1Database;
  EVENTS_DO: DurableObjectNamespace;
  KV: KVNamespace;
  RATELIMIT: RateLimit;
  USE_MOCKS: string;
}

export type { AppEnv };
